INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('q5ejsdqscjvqz2jz9riknq5ejsd0scv0', '2025-Q2', 'Jun/2025', '2025-06-15T21:21'::timestamptz, 'Dayane Chamarelli', 'dayane chamarelli', 'PHARUS', 'Gabriel Oliveira', 9.0, 'Promotor', 8.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', 'O conceito é interessante e eu recomendaria', NULL, NULL, 'O atendimento é interessante, no entanto acredito que precisa melhorar no sentido de ter mais proatividade em sugerir oportunidades de maneira contínua (não apenas na reunião inicial). Apenas para deixar claro, quando acionamos nosso estrategista ele sempre nos atende muito bem…porém ter ofertas constantes de oportunidades seria muito bom. Outro ponto a melhorar é que gostaríamos de entender um pouco mais sobre determinadas estratégias, como por exemplo o consórcio… se houvesse conteúdo adicional/treinamento para entender melhor as possível estratégias, poderíamos explorar melhor as possibilidades de aplicação nos nossos negócios já existentes e possíveis oportunidades. No geral o feedback é positivo, melhorando estes pontos o programa elevaria o nível de conexão conosco.', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', 'q5ejsdqscjvqz2jz9riknq5ejsd0scv0', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.prog